+}
+
+.intro {
+  margin: 0.75rem 0 0;
+  color: var(--muted);
+  max-width: 38ch;
+}
+
+form {
+  margin-top: 1.75rem;
+}
+
+fieldset {
+  margin: 0;
+  padding: 0;
+  border: 0;
+  min-width: 0;
+}
+
+legend {
+  padding: 0;
+  font-size: 1.1rem;
+  font-weight: 700;
+}
+
+.required-mark {
+  color: var(--accent-strong);
+}
+
+.hint {
+  margin: 0.5rem 0 1rem;
+  color: var(--muted);
+  font-size: 0.95rem;
+}
+
+.radio-list {
+  display: grid;
+  gap: 0.75rem;
+}
+
+.radio-option {
+  display: flex;
+  align-items: center;
+  gap: 0.75rem;
+  padding: 0.95rem 1rem;
+  border: 1px solid var(--border);
+  border-radius: 1rem;
+  background: var(--panel);
+  transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;
+}
+
+.radio-option:hover {
+  border-color: #3b4d76;
+  background: var(--panel-strong);
+}
+
+.radio-option input {
+  width: 1.1rem;
+  height: 1.1rem;
+  margin: 0;
+  accent-color: var(--accent);
+}
+
+.radio-option label {
+  cursor: pointer;
+  flex: 1;
+}
+
+.radio-option:has(input:focus-visible) {
